35	export const fetchEvents = async (fightId: number, params?: FetchEventsParams): Promise<Event[]> => {
36	  const query = new URLSearchParams();
37	  if (params) {
38	    Object.entries(params).forEach(([key, value]) => {
39	      if (value !== undefined) query.append(key, String(value));
40	    });
41	  }
42	  const qs = query.toString();
43	  const response = await fetch(`/fights/${fightId}/events/${qs ? `?${qs}` : ''}`);
44	  if (!response.ok) throw new Error(`Failed to fetch events: ${response.statusText}`);
45	  return response.json();
