1	import { useState, useEffect } from 'react';
2	import { fetchEvents, type FetchEventsParams } from '../services/api';
3	import type { Event } from '../types/Event';
4	
5	export const useEvents = (fightId?: number | null, params?: FetchEventsParams) => {
6	  const [events, setEvents] = useState<Event[]>([]);
7	  const [loading, setLoading] = useState<boolean>(true);
8	  const [error, setError] = useState<string | null>(null);
9	
10	  // `params` is typically passed as an inline object literal, so it's a new
11	  // reference every render — serialize it for the effect's dependency so we
12	  // only refetch when its actual contents change, not its identity.
13	  const paramsKey = JSON.stringify(params ?? {});
14	
15	  useEffect(() => {
16	    if (fightId == null) {
17	      setEvents([]);
18	      setLoading(false);
19	      return;
20	    }
21	    setLoading(true);
22	    setEvents([]);
23	    fetchEvents(fightId, params)
24	      .then(setEvents)
25	      .catch(err => setError(err instanceof Error ? err.message : 'An unknown error occurred'))
26	      .finally(() => setLoading(false));
27	    // eslint-disable-next-line react-hooks/exhaustive-deps
28	  }, [fightId, paramsKey]);
29	
30	  return { events, setEvents, loading, error };
31	};
