1	import { useCallback, useEffect, useState } from 'react';
2	import { fetchEvalRun, fetchEvalRuns, fetchFixtures, fetchFights } from '../services/api';
3	import { latestPerVersion } from '../types/EvalRun';
4	import type { EvalReport, EvalRunSummary, FixtureSummary } from '../types/EvalRun';
5	import type { Fight } from '../types/Fight';
6	import { useWindowWidth } from '../hooks/useWindowWidth';
7	import ClassificationBreakdown from '../components/accuracy/ClassificationBreakdown';
8	import ConfusionHeatmap from '../components/accuracy/ConfusionHeatmap';
9	import FixtureTable from '../components/accuracy/FixtureTable';
10	import Glossary from '../components/accuracy/Glossary';
11	import HeadlineF1 from '../components/accuracy/HeadlineF1';
12	import NotMeasurable from '../components/accuracy/NotMeasurable';
13	import OffsetDotStrip from '../components/accuracy/OffsetDotStrip';
14	import ProvenanceLine from '../components/accuracy/ProvenanceLine';
15	import RoundsCheck from '../components/accuracy/RoundsCheck';
16	import StateDumbbell from '../components/accuracy/StateDumbbell';
17	import VersionTrendChart from '../components/accuracy/VersionTrendChart';
18	import WorstList from '../components/accuracy/WorstList';
19	
20	/**
21	 * Training Lab, Section E only ("Pipeline accuracy") — see
22	 * ~/.claude/plans/i-have-now-reference-radiant-salamander.md. Sections
23	 * A-D/F/G of the full design need labelled-data volume/infrastructure this
24	 * app doesn't have yet; this page covers only what the current fixtures
25	 * (a labelled reference fight scored against a re-uploaded, AI-processed
26	 * copy of itself) can honestly show — E0/E1/E2/E8.
27	 */
28	export default function PipelineAccuracy() {
29	  const width = useWindowWidth();
30	  const isMobile = width < 640;
31	
32	  const [fixtures, setFixtures] = useState<FixtureSummary[]>([]);
33	  const [fights, setFights] = useState<Fight[]>([]);
34	  const [selectedId, setSelectedId] = useState<number | null>(null);
35	  const [runs, setRuns] = useState<EvalRunSummary[]>([]);
36	  /** `id` of the version being drilled into below the trend chart — not
37	   * necessarily the latest one; defaults to latest but the user can pick an
38	   * earlier version (including v1) via VersionTrendChart. */
39	  const [selectedRunId, setSelectedRunId] = useState<number | null>(null);
40	  const [report, setReport] = useState<EvalReport | null>(null);
41	  const [loading, setLoading] = useState(true);
42	  const [error, setError] = useState<string | null>(null);
43	
44	  const loadFixtures = useCallback(() => {
45	    setLoading(true);
46	    Promise.all([fetchFixtures(), fetchFights()])
47	      .then(([fx, fl]) => {
48	        setFixtures(fx);
49	        setFights(fl);
50	        setSelectedId((prev) => {
51	          if (prev !== null && fx.some((f) => f.reference_fight_id === prev)) return prev;
52	          const measurable = fx.find((f) => f.is_measurable);
53	          return (measurable ?? fx[0])?.reference_fight_id ?? null;
54	        });
55	      })
56	      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'))
57	      .finally(() => setLoading(false));
58	  }, []);
59	
60	  useEffect(() => { loadFixtures(); }, [loadFixtures]);
61	
62	  const selected = fixtures.find((f) => f.reference_fight_id === selectedId) ?? null;
63	
64	  useEffect(() => {
65	    if (!selected || !selected.is_measurable) {
66	      setRuns([]);
67	      setReport(null);
68	      return;
69	    }
70	    // Switching fixtures should default back to that fixture's latest
71	    // version, not carry over whatever version id was selected before.
72	    setSelectedRunId(null);
73	    fetchEvalRuns(selected.reference_fight_id)
74	      .then(setRuns)
75	      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'));
76	  }, [selected]);
77	
78	  const versions = latestPerVersion(runs);
79	  const selectedIndex = selectedRunId === null
80	    ? versions.length - 1
81	    : versions.findIndex((v) => v.id === selectedRunId);
82	  const current = selectedIndex >= 0 ? versions[selectedIndex] : null;
83	  const previous = current && selectedIndex > 0 ? versions[selectedIndex - 1] : null;
84	  const currentRunId = current?.id ?? null;
85	
86	  useEffect(() => {
87	    if (currentRunId === null) {
88	      setReport(null);
89	      return;
90	    }
91	    fetchEvalRun(currentRunId)
92	      .then((r) => setReport(r.report))
93	      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'));
94	  }, [currentRunId]);
95	
96	  const candidates = fights.filter((f) => f.purpose === 'ai_labeled' && f.state === 'completed');
97	
98	  return (
99	    <div style={{ maxWidth: 1440, margin: '0 auto', padding: isMobile ? '14px 13px 60px' : '22px 30px 80px', width: '100%' }}>
100	      <div style={{ marginBottom: 16 }}>
101	        <h1 className="font-display" style={{ fontSize: isMobile ? 30 : 40, lineHeight: 0.94, margin: 0, color: 'var(--text-primary)' }}>
102	          PIPELINE ACCURACY
103	        </h1>
104	        <p style={{ margin: '5px 0 0', fontSize: 12.5, fontWeight: 600, color: 'var(--text-muted)' }}>
105	          Reference fixtures scored against pipeline predictions, across versions
106	        </p>
107	      </div>
108	
109	      {loading && <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Loading…</div>}
110	      {error && <div style={{ fontSize: 13, color: 'var(--red-500)', marginBottom: 14 }}>{error}</div>}
111	
112	      {!loading && fixtures.length === 0 && (
113	        <div className="glass" style={{ padding: '20px 22px', fontSize: 13, color: 'var(--text-muted)' }}>
114	          No labelled reference fixture exists yet. Upload a fight as "Self-annotate → Reference" and
115	          finish labelling it to create one.
116	        </div>
117	      )}
118	
119	      {fixtures.length > 0 && (
120	        <div className="glass" style={{ padding: '20px 22px 22px', marginBottom: 16 }}>
121	          <div className="label" style={{ marginBottom: 12 }}>Fixtures</div>
122	          <FixtureTable fixtures={fixtures} selectedId={selectedId} onSelect={setSelectedId} />
123	          <Glossary />
124	        </div>
125	      )}
126	
127	      {selected && (
128	        <div className="glass" style={{ padding: '20px 22px 22px' }}>
129	          {!selected.is_measurable ? (
130	            <NotMeasurable fixture={selected} candidates={candidates} onScored={loadFixtures} />
131	          ) : current ? (
132	            <>
133	              <div style={{ marginBottom: 16 }}>
134	                <ProvenanceLine run={current} />
135	              </div>
136	              <div style={{ marginBottom: 20 }}>
137	                <HeadlineF1 current={current} previous={previous} />
138	              </div>
139	              <div style={{ marginBottom: 20 }}>
140	                <div className="label" style={{ marginBottom: 11 }}>Accuracy history — this fixture, every pipeline version</div>
141	                <VersionTrendChart versions={versions} selectedId={current.id} onSelect={setSelectedRunId} />
142	              </div>
143	
144	              {report && (
145	                <div style={{ display: 'flex', flexDirection: 'column', gap: 20, paddingTop: 18, borderTop: '1px solid rgba(255,255,255,0.05)' }}>
146	                  <div>
147	                    <div className="label" style={{ marginBottom: 11 }}>Classification — matched strikes only</div>
148	                    <ClassificationBreakdown strikes={report.strikes} />
149	                  </div>
150	
151	                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 20 }}>
152	                    <div>
153	                      <div className="label" style={{ marginBottom: 11 }}>Strike family confusion</div>
154	                      <ConfusionHeatmap confusion={report.strikes.family_confusion} emptyLabel="No specific-family matches yet." />
155	                    </div>
156	                    <div>
157	                      <div className="label" style={{ marginBottom: 11 }}>Timing</div>
158	                      <OffsetDotStrip offsets={report.strikes.matched_offsets} />
159	                    </div>
160	                  </div>
161	
162	                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 20 }}>
163	                    <div>
164	                      <div className="label" style={{ marginBottom: 11 }}>Fight state</div>
165	                      <StateDumbbell state={report.state} />
166	                      <div style={{ marginTop: 12 }}>
167	                        <ConfusionHeatmap confusion={report.state.confusion} emptyLabel="No state frames scored yet." />
168	                      </div>
169	                    </div>
170	                    <div>
171	                      <div className="label" style={{ marginBottom: 11 }}>Rounds</div>
172	                      <RoundsCheck rounds={report.rounds} />
173	                    </div>
174	                  </div>
175	
176	                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: 20 }}>
177	                    <WorstList title="Worst misses" fps={report.fps} items={report.strikes.missed} emptyLabel="No missed strikes." />
178	                    <WorstList title="Worst false positives" fps={report.fps} items={report.strikes.spurious} emptyLabel="No false positives." />
179	                  </div>
180	                </div>
181	              )}
182	            </>
183	          ) : (
184	            <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Loading runs…</div>
185	          )}
186	        </div>
187	      )}
188	    </div>
189	  );
190	}
