1	/**
2	 * Single source of truth for the manual-annotation palette: each ToolItem
3	 * drives the palette button, its keyboard shortcut, and the keyboard legend
4	 * simultaneously. Round boundaries aren't here — real Round rows already
5	 * exist from AI segmentation (see ai/fight_processing/write_frames_and_rounds).
6	 * Only "fight end" stays manual since no stage detects a fight's conclusion.
7	 */
8	
9	import type { EventCat } from '../../utils/eventTaxonomy';
10	export type { EventCat };
11	
12	export type Corner = 'red' | 'blue';
13	export type Target = 'head' | 'body' | 'leg';
14	// The three range-shaped (kind != 'point') Event rows Annotate edits.
15	export type SpanKind = 'round' | 'corner_swap' | 'excluded';
16	
17	export interface ToolItem {
18	  key: string;
19	  num?: string;
20	  action: string;
21	  name: string;
22	  text: (fighterName: string, target?: Target) => string;
23	  needsFighter: boolean;
24	  /** Shift-modified: plain key = head, Shift+key = body. Read via e.code + e.shiftKey. */
25	  hasTarget?: boolean;
26	  /** Kicks already encode target in the action name — no modifier needed. */
27	  fixedTarget?: Target;
28	}
29	
30	export interface ToolGroup {
31	  group: string;
32	  note?: string;
33	  items: ToolItem[];
34	}
35	
36	// Shared by every hand strike + elbow so the description always reflects the
37	// real target instead of a value baked in per-action (right_hook used to be
38	// hardcoded "to the body" regardless of where it actually landed).
39	//
40	// jab/cross are lead/rear-relative (boxing terms), not absolute-handed —
41	// a southpaw's jab is thrown with their right hand. Hooks/uppercuts stay
