20	  const holdTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
21	  const holdIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
22	  const isHoldingRef = useRef(false);
23	
24	  const [ppOverlay, setPpOverlay] = useState<{ icon: string; key: number } | null>(null);
