26	  const [seekFading, setSeekFading] = useState(false);
27	
28	  const stopHold = useCallback(() => {
29	    if (holdTimeoutRef.current) {
30	      clearTimeout(holdTimeoutRef.current);
31	      holdTimeoutRef.current = null;
32	    }
33	    if (holdIntervalRef.current) {
34	      clearInterval(holdIntervalRef.current);
35	      holdIntervalRef.current = null;
36	    }
37	  }, []);
38	
39	  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
40	    const rect = e.currentTarget.getBoundingClientRect();
41	    const isRight = (e.clientX - rect.left) > rect.width / 2;
42	    const stepFn = isRight ? onStepForward : onStepBackward;
43	
44	    holdTimeoutRef.current = setTimeout(() => {
45	      isHoldingRef.current = true;
46	      setSeekDir(isRight ? 'right' : 'left');
47	      setSeekFading(false);
48	      stepFn();
49	      holdIntervalRef.current = setInterval(stepFn, 80);
50	    }, 250);
51	  }, [onStepForward, onStepBackward]);
52	
53	  const handleMouseUp = useCallback(() => {
54	    if (isHoldingRef.current) {
55	      stopHold();
56	      setSeekFading(true);
57	      isHoldingRef.current = false;
58	    } else {
59	      stopHold();
60	      setPpOverlay(prev => ({
61	        icon: isPlaying ? 'pause' : 'play_arrow',
62	        key: (prev?.key ?? 0) + 1,
63	      }));
64	      onTogglePlay();
65	    }
66	  }, [isPlaying, onTogglePlay, stopHold]);
67	
68	  const handleMouseLeave = useCallback(() => {
69	    if (isHoldingRef.current) {
70	      stopHold();
71	      setSeekFading(true);
72	      isHoldingRef.current = false;
73	    } else {
74	      stopHold();
75	    }
76	  }, [stopHold]);
77	
78	  const overlayBase: React.CSSProperties = {
79	    position: 'absolute',
80	    top: '50%',
81	    fontSize: 64,
82	    color: '#fff',
83	    pointerEvents: 'none',
84	    background: 'rgba(0,0,0,0.35)',
85	    borderRadius: '50%',
86	    padding: 14,
87	    lineHeight: 1,
88	  };
89	
90	  return (
91	    <div
92	      style={{ position: 'relative', lineHeight: 0, cursor: 'pointer', borderRadius: 8, overflow: 'hidden' }}
93	      onMouseDown={handleMouseDown}
94	      onMouseUp={handleMouseUp}
95	      onMouseLeave={handleMouseLeave}
96	    >
97	      <video
98	        ref={ref}
99	        src={src}
100	        onTimeUpdate={onTimeUpdate}
101	        onLoadedMetadata={onLoadedMetadata}
