111	          className="material-symbols-outlined"
112	          onAnimationEnd={() => setPpOverlay(null)}
113	          style={{
114	            ...overlayBase,
115	            left: '50%',
116	            fontSize: 72,
117	            animation: 'video-feedback 0.5s ease-out forwards',
118	          }}
119	        >
120	          {ppOverlay.icon}
121	        </span>
122	      )}
123	
124	      {/* Seek overlay */}
