128	          onAnimationEnd={() => {
129	            if (seekFading) {
130	              setSeekDir(null);
131	              setSeekFading(false);
132	            }
133	          }}
134	          style={{
135	            ...overlayBase,
136	            left: seekDir === 'left' ? '25%' : '75%',
137	            animation: seekFading
138	              ? 'seek-fade 0.3s ease-out forwards'
139	              : 'seek-pulse 0.6s ease-in-out infinite',
140	          }}
141	        >
142	          {seekDir === 'left' ? 'fast_rewind' : 'fast_forward'}
143	        </span>
144	      )}
145	
146	      {children}
147	    </div>
148	  );
149	});
