5	// COCO-17 skeleton edges — matches pose_verification.py
6	const SKELETON_EDGES: [number, number][] = [
7	  [0, 1], [0, 2], [1, 3], [2, 4],
8	  [0, 5], [0, 6],
9	  [5, 7], [7, 9],
10	  [6, 8], [8, 10],
11	  [5, 6],
