21	// Matches the fighter-corner-btn selected-state fill (`color-mix(in srgb, ${color} 12%, transparent)`).
22	function withAlpha(hex: string, alpha: number): string {
23	  const r = parseInt(hex.slice(1, 3), 16);
24	  const g = parseInt(hex.slice(3, 5), 16);
25	  const b = parseInt(hex.slice(5, 7), 16);
26	  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
