29	interface FighterOverlayProps {
30	  frameMap: Map<number, FighterFrame[]>;
31	  fightWidth: number;
32	  fightHeight: number;
33	  showBoxes: boolean;
34	  showSkeletons: boolean;
35	  /** Corner (0 = red, 1 = blue) of the fighter the user has selected. No box is drawn until this is set. */
36	  highlightCorner?: 0 | 1 | null;
37	  /**
38	   * Hand-labelled stretches where the tracker's red/blue assignment is known
39	   * to be flipped (`fighter_frames.corner` is deliberately left uncorrected —
40	   * see label-events-corner-is-box-not-person). When the current frame falls
41	   * inside one of these, box/skeleton colour is flipped for **display only**;
42	   * nothing about the underlying data changes.
