51	const FighterOverlay = forwardRef<FighterOverlayHandle, FighterOverlayProps>(
52	  ({ frameMap, fightWidth, fightHeight, showBoxes, showSkeletons, highlightCorner = null, cornerSwapSpans = [] }, ref) => {
53	    const canvasRef = useRef<HTMLCanvasElement>(null);
54	    const frameMapRef = useRef(frameMap);
55	    const fightWidthRef = useRef(fightWidth);
56	    const fightHeightRef = useRef(fightHeight);
57	    const showBoxesRef = useRef(showBoxes);
58	    const showSkeletonsRef = useRef(showSkeletons);
59	    const highlightCornerRef = useRef(highlightCorner);
60	    const cornerSwapSpansRef = useRef(cornerSwapSpans);
61	    const lastFrameRef = useRef(1);
62	
63	    useEffect(() => { frameMapRef.current = frameMap; }, [frameMap]);
64	    useEffect(() => { fightWidthRef.current = fightWidth; }, [fightWidth]);
65	    useEffect(() => { fightHeightRef.current = fightHeight; }, [fightHeight]);
66	    useEffect(() => { showBoxesRef.current = showBoxes; }, [showBoxes]);
67	    useEffect(() => { showSkeletonsRef.current = showSkeletons; }, [showSkeletons]);
68	    useEffect(() => { cornerSwapSpansRef.current = cornerSwapSpans; }, [cornerSwapSpans]);
69	
70	    const render = () => {
71	      const canvas = canvasRef.current;
72	      if (!canvas) return;
73	      const ctx = canvas.getContext('2d');
74	      if (!ctx) return;
75	
76	      if (canvas.width !== canvas.clientWidth || canvas.height !== canvas.clientHeight) {
77	        canvas.width = canvas.clientWidth;
78	        canvas.height = canvas.clientHeight;
79	      }
80	      ctx.clearRect(0, 0, canvas.width, canvas.height);
81	
82	      const drawSkeletons = showSkeletonsRef.current;
83	      const drawBoxes = showBoxesRef.current;
84	      if (!drawBoxes && !drawSkeletons) return;
85	
86	      const frame = lastFrameRef.current;
87	      const detections = frameMapRef.current.get(frame);
88	      if (!detections) return;
89	
90	      const scaleX = canvas.width / fightWidthRef.current;
91	      const scaleY = canvas.height / fightHeightRef.current;
92	      const highlight = highlightCornerRef.current;
93	      // Display-only correction: a confirmed corner_swap span means the
94	      // tracker's red/blue assignment is known-flipped here. fighter_frames.corner
95	      // itself is never touched (see the prop docs above) — only which
96	      // colour we draw it as.
97	      const swapped = isFrameSwapped(frame, cornerSwapSpansRef.current);
98	
99	      for (const d of detections) {
100	        const displayCorner = swapped ? 1 - d.corner : d.corner;
101	        const color = displayCorner === 0 ? COLOR_RED : COLOR_BLUE;
102	        const isSelected = highlight !== null && highlight === d.corner;
103	
104	        // The box stays hidden until this fighter's corner is selected. Static styling
105	        // mirrors the selected fighter-corner-btn (tinted fill + glow, no motion).
106	        if (drawBoxes && isSelected) {
107	          const x = d.x1 * scaleX;
108	          const y = d.y1 * scaleY;
109	          const w = (d.x2 - d.x1) * scaleX;
110	          const h = (d.y2 - d.y1) * scaleY;
111	
112	          const radius = Math.min(12, w / 2, h / 2);
113	
114	          ctx.save();
115	          ctx.beginPath();
116	          ctx.roundRect(x, y, w, h, radius);
117	          ctx.fillStyle = withAlpha(color, 0.12);
118	          ctx.fill();
119	
120	          ctx.shadowColor = color;
121	          ctx.shadowBlur = 14;
122	          ctx.strokeStyle = color;
123	          ctx.lineWidth = 2;
124	          ctx.stroke();
125	          ctx.restore();
126	        }
127	
128	        if (drawSkeletons && d.keypoints && d.keypoints.length === 17) {
129	          ctx.strokeStyle = color;
130	          ctx.fillStyle = color;
131	          ctx.lineWidth = 1.5;
132	
133	          // Draw skeleton edges
134	          for (const [a, b] of SKELETON_EDGES) {
135	            const pa = d.keypoints[a];
136	            const pb = d.keypoints[b];
137	            if (!pa || !pb) continue;
138	            const ax = pa[0] * scaleX;
139	            const ay = pa[1] * scaleY;
140	            const bx = pb[0] * scaleX;
141	            const by = pb[1] * scaleY;
142	            ctx.beginPath();
143	            ctx.moveTo(ax, ay);
144	            ctx.lineTo(bx, by);
145	            ctx.stroke();
146	          }
147	
148	          // Draw joint dots
149	          for (const kp of d.keypoints) {
150	            if (!kp) continue;
151	            ctx.beginPath();
152	            ctx.arc(kp[0] * scaleX, kp[1] * scaleY, 3, 0, Math.PI * 2);
