166	    useEffect(() => {
167	      highlightCornerRef.current = highlightCorner;
168	      render();
169	      // eslint-disable-next-line react-hooks/exhaustive-deps
170	    }, [highlightCorner]);
171	
172	    return (
173	      <canvas
174	        ref={canvasRef}
175	        style={{
176	          position: 'absolute',
177	          top: 0,
178	          left: 0,
179	          width: '100%',
180	          height: '100%',
181	          pointerEvents: 'none',
182	        }}
183	      />
184	    );
185	  },
186	);
