5	export const useFighterFrames = (fightId: number | null) => {
6	  const [frameMap, setFrameMap] = useState<Map<number, FighterFrame[]>>(new Map());
7	  const [loading, setLoading] = useState(false);
8	
9	  useEffect(() => {
10	    if (fightId == null) return;
11	    setLoading(true);
12	    fetchFighterFrames(fightId)
13	      .then(frames => {
14	        const map = new Map<number, FighterFrame[]>();
15	        for (const f of frames) {
16	          const bucket = map.get(f.frame);
17	          if (bucket) bucket.push(f);
18	          else map.set(f.frame, [f]);
19	        }
20	        setFrameMap(map);
21	      })
22	      .finally(() => setLoading(false));
23	  }, [fightId]);
24	
25	  return { frameMap, loading };
26	};
