import { TOOL_GROUPS } from '../components/annotate/taxonomy';

/**
 * The subset of Annotate's palette that is actually a training class with a
 * reviewable clip: `needsFighter` point events minus takedown_attempt/
 * takedown_defended/submission_attempt/knockdown (captured but never
 * exported — see ai/eval/README.md's reference table) and every
 * `state_*` mark (a change point, not a per-event clip). Grouping mirrors
 * `TOOL_GROUPS` so this reads the same as the Annotate palette.
 */
export interface TrainingClass {
  action: string;
  name: string;
  group: string;
}

const NOT_A_CLASS = new Set([
  'takedown_attempt',
  'takedown_defended',
  'submission_attempt',
  'knockdown',
]);

export const TRAINING_CLASSES: TrainingClass[] = TOOL_GROUPS.flatMap((g) =>
  g.items
    .filter((it) => it.needsFighter && !NOT_A_CLASS.has(it.action))
    .map((it) => ({ action: it.action, name: it.name, group: g.group })),
);

export const TRAINING_ACTIONS = new Set(TRAINING_CLASSES.map((c) => c.action));

export const CLASS_BY_ACTION: Record<string, TrainingClass> =
  Object.fromEntries(TRAINING_CLASSES.map((c) => [c.action, c]));

import { useState, useEffect, useCallback } from 'react';
import { fetchFights, fetchEvents, verifyEvent } from '../services/api';
import type { Fight } from '../types/Fight';
import type { Event } from '../types/Event';
import { TRAINING_ACTIONS } from '../utils/trainingDataTaxonomy';

export interface QAEvent extends Event {
  fight: Fight;
}

/**
 * Every reviewable hand-labelled point event across every labelled fight —
 * Training Data QA is cross-fight, unlike Player/Annotate which scope to one
 * `fightId`. Only `training_data`/`reference` fights that have actually
 * reached Annotate carry `source='label'` rows; an `ai_labeled` fight's
 * pipeline run never writes one.
 */
export const useTrainingDataEvents = () => {
  const [events, setEvents] = useState<QAEvent[]>([]);
  const [fights, setFights] = useState<Fight[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(() => {
    setLoading(true);
    setError(null);
    fetchFights()
      .then(async (allFights) => {
        const labelled = allFights.filter(
          (f) => f.purpose !== 'ai_labeled'
            && (f.state === 'labeling_in_progress' || f.state === 'labeling_complete'),
        );
        setFights(labelled);
        const perFight = await Promise.all(
          labelled.map((f) =>
            fetchEvents(f.id, { source: 'label', kind: 'point' }).then((evs) =>
              evs
                .filter((e) => TRAINING_ACTIONS.has(e.action ?? ''))
                .map((e) => ({ ...e, fight: f })),
            ),
          ),
        );
        setEvents(perFight.flat());
      })
      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { load(); }, [load]);

  const setVerdict = useCallback((eventId: number, fightId: number, isVerified: boolean | null) => {
    setEvents((prev) => prev.map((e) => (e.id === eventId ? { ...e, is_verified: isVerified } : e)));
    verifyEvent(fightId, eventId, isVerified).catch(() => {
      // Roll back to the server's actual state on failure.
      load();
    });
  }, [load]);

  return { events, fights, loading, error, setVerdict, refetch: load };
};

import type { QAEvent } from '../../hooks/useTrainingDataEvents';
import { TRAINING_CLASSES } from '../../utils/trainingDataTaxonomy';

export interface ClassStats {
  total: number;
  confirmed: number;
  declined: number;
  reviewed: number;
  pending: number;
}

export function classStats(events: QAEvent[]): ClassStats {
  let confirmed = 0;
  let declined = 0;
  events.forEach((e) => {
    if (e.is_verified === true) confirmed++;
    else if (e.is_verified === false) declined++;
  });
  return { total: events.length, confirmed, declined, reviewed: confirmed + declined, pending: events.length - confirmed - declined };
}

interface ClassGridProps {
  eventsByAction: Map<string, QAEvent[]>;
  onOpen: (action: string) => void;
}

export default function ClassGrid({ eventsByAction, onOpen }: ClassGridProps) {
  const groups: { name: string; items: typeof TRAINING_CLASSES }[] = [];
  TRAINING_CLASSES.forEach((c) => {
    let g = groups.find((x) => x.name === c.group);
    if (!g) { g = { name: c.group, items: [] }; groups.push(g); }
    g.items.push(c);
  });

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 22 }}>
      {groups.map((g) => (
        <section key={g.name}>
          <div className="label" style={{ paddingBottom: 8, marginBottom: 12, borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
            {g.name}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: 12 }}>
            {g.items.map((c) => {
              const evs = eventsByAction.get(c.action) ?? [];
              const s = classStats(evs);
              return (
                <button
                  key={c.action}
                  type="button"
                  className="glass"
                  onClick={() => onOpen(c.action)}
                  disabled={s.total === 0}
                  style={{
                    display: 'flex', flexDirection: 'column', gap: 9, padding: '13px 14px 14px', textAlign: 'left',
                    cursor: s.total === 0 ? 'default' : 'pointer', fontFamily: 'inherit', transition: 'border-color .14s, transform .14s',
                    opacity: s.total === 0 ? 0.45 : 1,
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, minWidth: 0 }}>
                    <span style={{ fontSize: 13, fontWeight: 800, color: 'var(--text-primary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      {c.name}
                    </span>
                    <span className="material-symbols-outlined" style={{ fontSize: 17, color: 'var(--text-disabled)', marginLeft: 'auto' }}>chevron_right</span>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'baseline', gap: 6 }}>
                    <span className="font-display" style={{ fontSize: 24, lineHeight: 1, color: 'var(--text-primary)' }}>{s.total}</span>
                    <span style={{ fontSize: 10.5, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.08em', color: 'var(--text-muted)' }}>events</span>
                  </div>
                  {s.total > 0 && (
                    <div style={{ display: 'flex', gap: 2, height: 4, borderRadius: 2, background: 'rgba(255,255,255,0.05)', overflow: 'hidden' }}>
                      <div style={{ background: '#0ca30c', width: `${(s.confirmed / s.total) * 100}%` }} />
                      <div style={{ background: '#ef4444', width: `${(s.declined / s.total) * 100}%` }} />
                    </div>
                  )}
                  <div style={{ fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>
                    {s.total === 0 ? 'No events yet' : s.reviewed === 0 ? 'Not reviewed' : `${s.reviewed}/${s.total} reviewed`}
                    {s.declined > 0 && <span style={{ color: '#ef4444' }}> · {s.declined} declined</span>}
                  </div>
                </button>
              );
            })}
          </div>
        </section>
      ))}
    </div>
  );
}

