const VERDICT: Record<'confirmed' | 'declined' | 'pending', { c: string; icon: string; t: string }> = {
  confirmed: { c: '#0ca30c', icon: 'check_circle', t: 'Confirmed' },
  declined: { c: '#ef4444', icon: 'cancel', t: 'Declined' },
  pending: { c: '#64748b', icon: 'schedule', t: 'Pending' },
};

export function verdictKey(isVerified: boolean | null): 'confirmed' | 'declined' | 'pending' {
  if (isVerified === true) return 'confirmed';
  if (isVerified === false) return 'declined';
  return 'pending';
}

interface VerdictBadgeProps {
  isVerified: boolean | null;
  sm?: boolean;
}

export default function VerdictBadge({ isVerified, sm }: VerdictBadgeProps) {
  const m = VERDICT[verdictKey(isVerified)];
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: 4, whiteSpace: 'nowrap',
      padding: sm ? '2px 6px' : '3px 8px', borderRadius: 6,
      background: `color-mix(in srgb, ${m.c} 13%, transparent)`,
      border: `1px solid color-mix(in srgb, ${m.c} 26%, transparent)`,
      color: m.c, fontSize: sm ? 10 : 11, fontWeight: 700,
    }}>
      <span className="material-symbols-outlined" style={{ fontSize: sm ? 11 : 12 }}>{m.icon}</span>
      {m.t}
    </span>
  );
}

import { useState } from 'react';
import type { QAEvent } from '../../hooks/useTrainingDataEvents';
import type { TrainingClass } from '../../utils/trainingDataTaxonomy';
import { formatFrameClock } from '../annotate/taxonomy';
import { fightLabel } from '../../utils/fightLabel';
import VerdictBadge, { verdictKey } from './VerdictBadge';
import { classStats } from './ClassGrid';

const CORNER_C: Record<number, string> = { 0: 'var(--f-red)', 1: 'var(--f-blue)' };
const FILTERS = ['All', 'Pending', 'Confirmed', 'Declined'] as const;

interface EventTableProps {
  cls: TrainingClass;
  events: QAEvent[];
  onBack: () => void;
  onOpen: (id: number) => void;
}

export default function EventTable({ cls, events, onBack, onOpen }: EventTableProps) {
  const [filter, setFilter] = useState<(typeof FILTERS)[number]>('All');
  const [fightId, setFightId] = useState<number | 'all'>('all');

  const s = classStats(events);
  const fights = [...new Map(events.map((e) => [e.fight.id, e.fight])).values()];

  const rows = events
    .filter((e) => {
      const v = verdictKey(e.is_verified);
      if (filter === 'Pending' && v !== 'pending') return false;
      if (filter === 'Confirmed' && v !== 'confirmed') return false;
      if (filter === 'Declined' && v !== 'declined') return false;
      if (fightId !== 'all' && e.fight.id !== fightId) return false;
      return true;
    })
    .sort((a, b) => (a.fight.id === b.fight.id ? a.frame - b.frame : a.fight.id - b.fight.id));

  const firstPending = events.find((e) => e.is_verified == null);

  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 9, marginBottom: 14, flexWrap: 'wrap' }}>
        <button type="button" className="btn-glass" onClick={onBack} style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '5px 10px', fontSize: 11.5, fontWeight: 700, borderRadius: 8 }}>
          <span className="material-symbols-outlined" style={{ fontSize: 15 }}>arrow_back</span>All classes
        </button>
        <span style={{ color: 'var(--text-disabled)', fontSize: 12 }}>/</span>
        <span style={{ fontSize: 11.5, fontWeight: 700, color: 'var(--text-secondary)' }}>{cls.name}</span>
      </div>

      <div style={{ display: 'flex', alignItems: 'flex-end', gap: 18, flexWrap: 'wrap', marginBottom: 16 }}>
        <div style={{ minWidth: 0 }}>
          <h1 className="font-display" style={{ fontSize: 32, lineHeight: 0.94, margin: 0, color: 'var(--text-primary)' }}>{cls.name}</h1>
          <p style={{ margin: '5px 0 0', fontSize: 12.5, fontWeight: 600, color: 'var(--text-muted)' }}>
            {s.total} labelled events · exports as <code style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 11.5, color: '#9fe8f4' }}>{cls.action}</code>
          </p>
        </div>
        <button
          type="button"
          className="btn-primary"
          disabled={!firstPending}
          onClick={() => firstPending && onOpen(firstPending.id)}
          style={{
            marginLeft: 'auto', background: 'linear-gradient(135deg, #00daf3 0%, #0099b0 100%)', color: '#001f24',
            fontWeight: 700, fontSize: 13, border: 'none', borderRadius: 10, padding: '9px 16px',
            display: 'inline-flex', alignItems: 'center', gap: 6,
            boxShadow: firstPending ? '0 0 16px rgba(0,218,243,0.2)' : 'none', opacity: firstPending ? 1 : 0.45,
            cursor: firstPending ? 'pointer' : 'default',
          }}
        >
          <span className="material-symbols-outlined" style={{ fontSize: 16 }}>play_arrow</span>
          {s.pending ? `Review ${s.pending} pending` : 'All reviewed'}
        </button>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 11, flexWrap: 'wrap', padding: '9px 12px', marginBottom: 14, borderRadius: 12, background: 'rgba(255,255,255,0.028)', border: '1px solid var(--border-subtle)' }}>
        <div style={{ display: 'flex', gap: 4, padding: 3, borderRadius: 9, background: 'rgba(0,0,0,0.28)', border: '1px solid var(--border-subtle)' }}>
          {FILTERS.map((f) => (
            <button key={f} type="button" className={'pill' + (filter === f ? ' active' : '')} onClick={() => setFilter(f)} style={{ padding: '4px 9px', fontSize: 11 }}>{f}</button>
          ))}
        </div>
        {fights.length > 1 && (
          <>
            <span style={{ width: 1, height: 20, background: 'rgba(255,255,255,0.08)' }} />
            <div style={{ display: 'flex', gap: 4, padding: 3, borderRadius: 9, background: 'rgba(0,0,0,0.28)', border: '1px solid var(--border-subtle)', flexWrap: 'wrap' }}>
              <button type="button" className={'pill' + (fightId === 'all' ? ' active' : '')} onClick={() => setFightId('all')} style={{ padding: '4px 9px', fontSize: 11 }}>All fights</button>
              {fights.map((f) => (
                <button key={f.id} type="button" className={'pill' + (fightId === f.id ? ' active' : '')} onClick={() => setFightId(f.id)} style={{ padding: '4px 9px', fontSize: 11 }}>
                  {fightLabel(f).split(' vs ')[0]}
                </button>
              ))}
            </div>
          </>
        )}
        <span style={{ flex: 1 }} />
        <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-muted)' }}>{rows.length} shown</span>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {rows.map((e) => (
          <button
            key={e.id}
            type="button"
            onClick={() => onOpen(e.id)}
            style={{
              display: 'grid', gridTemplateColumns: '74px minmax(0,1fr) auto auto 18px', gap: 13, alignItems: 'center',
              padding: '10px 12px', borderRadius: 11, background: 'rgba(255,255,255,0.022)', border: '1px solid var(--border-subtle)',
              cursor: 'pointer', fontFamily: 'inherit', textAlign: 'left',
            }}
          >
            <span style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 12, fontWeight: 700, color: 'var(--text-primary)' }}>
              {formatFrameClock(e.frame, e.fight.fps)}
            </span>
            <span style={{ display: 'flex', flexDirection: 'column', gap: 3, minWidth: 0 }}>
              <span style={{ fontSize: 12, fontWeight: 800, color: 'var(--text-secondary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {fightLabel(e.fight)}
              </span>
              <span style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>
                <span style={{ width: 7, height: 7, borderRadius: 2, background: e.corner != null ? CORNER_C[e.corner] : 'var(--text-disabled)', flexShrink: 0 }} />
                {e.corner === 0 ? 'Red slot' : e.corner === 1 ? 'Blue slot' : 'No corner'} · {e.target ?? 'non-specific'}
              </span>
            </span>
            <VerdictBadge isVerified={e.is_verified} sm />
            <span className="material-symbols-outlined" style={{ fontSize: 16, color: 'var(--text-disabled)' }}>chevron_right</span>
          </button>
        ))}
        {rows.length === 0 && (
          <div style={{ padding: 26, textAlign: 'center', fontSize: 12, fontWeight: 600, color: 'var(--text-muted)' }}>
            No events match this filter.
          </div>
        )}
      </div>
    </div>
  );
}

import { useRef, useState, useEffect, useCallback } from 'react';
import type { Fight } from '../../types/Fight';
import { useFighterFrames } from '../../hooks/useFighterFrames';
import { useEvents } from '../../hooks/useEvents';
import FighterOverlay, { type FighterOverlayHandle } from '../FighterOverlay';

const CLIP_HALF_WINDOW_SECS = 1.2;

interface ClipPlayerProps {
  fight: Fight;
  frame: number; // the reviewed event's frame (1-based)
  corner: number | null;
}

/**
 * A short, looping window of the real fight video around one labelled
 * event's frame, with the real FighterOverlay boxes/skeletons drawn on top —
 * reuses the same frame-numbering contract and requestVideoFrameCallback
 * draw loop as Player.tsx, just scoped to a ~2.4s window instead of the
 * whole fight.
 */
export default function ClipPlayer({ fight, frame, corner }: ClipPlayerProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const overlayRef = useRef<FighterOverlayHandle>(null);
  const rafRef = useRef<number | null>(null);
  const [isPlaying, setIsPlaying] = useState(true);
  const [showBoxes, setShowBoxes] = useState(true);
  const [showSkeletons, setShowSkeletons] = useState(true);
  const [speed, setSpeed] = useState(1);
  const [currentTime, setCurrentTime] = useState(0);

  const { frameMap } = useFighterFrames(fight.id);
  const { events: swapEvents } = useEvents(fight.id, { source: 'label', kind: 'corner_swap' });
  const cornerSwapSpans = swapEvents.map((e) => ({ frame: e.frame, end_frame: e.end_frame }));

  const fps = fight.fps;
  const eventTime = (frame - 1) / fps;
  const windowStart = Math.max(0, eventTime - CLIP_HALF_WINDOW_SECS);
  const windowEnd = eventTime + CLIP_HALF_WINDOW_SECS;

  // Jump to the event's window whenever the reviewed event changes.
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    const seek = () => {
      video.currentTime = windowStart;
      video.playbackRate = speed;
      setCurrentTime(windowStart);
      video.play().catch(() => {});
      setIsPlaying(true);
    };
    if (video.readyState >= 1) seek();
    else video.addEventListener('loadedmetadata', seek, { once: true });
    return () => video.removeEventListener('loadedmetadata', seek);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fight.id, frame]);

  useEffect(() => {
    const video = videoRef.current;
    if (video) video.playbackRate = speed;
  }, [speed]);

  // Loop playback within [windowStart, windowEnd] and draw the overlay per frame.
  useEffect(() => {
    const video = videoRef.current;
    if (!video || !isPlaying) {
      if (rafRef.current !== null && video) {
        video.cancelVideoFrameCallback(rafRef.current);
        rafRef.current = null;
      }
      return;
    }
    const tick = (_now: DOMHighResTimeStamp, metadata: VideoFrameCallbackMetadata) => {
      let t = metadata.mediaTime;
      if (t >= windowEnd) {
        video.currentTime = windowStart;
        t = windowStart;
      }
      overlayRef.current?.draw(Math.floor(t * fps) + 1);
      setCurrentTime(t);
      rafRef.current = video.requestVideoFrameCallback(tick);
    };
    rafRef.current = video.requestVideoFrameCallback(tick);
    return () => {
      if (rafRef.current !== null) video.cancelVideoFrameCallback(rafRef.current);
      rafRef.current = null;
    };
  }, [isPlaying, windowStart, windowEnd, fps]);

  const togglePlay = useCallback(() => {
    const video = videoRef.current;
    if (!video) return;
    if (isPlaying) { video.pause(); setIsPlaying(false); } else { video.play().catch(() => {}); setIsPlaying(true); }
  }, [isPlaying]);

  const handleScrub = (t: number) => {
    const video = videoRef.current;
    if (!video) return;
    video.pause();
    setIsPlaying(false);
    video.currentTime = t;
    setCurrentTime(t);
    overlayRef.current?.draw(Math.floor(t * fps) + 1);
  };

  const clipFrame = Math.floor((currentTime - windowStart) * fps) + 1;
  const clipFrames = Math.max(1, Math.round((windowEnd - windowStart) * fps));

  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 9, flexWrap: 'wrap', marginBottom: 10 }}>
        <button type="button" className={'pill' + (showSkeletons ? ' active' : '')} onClick={() => setShowSkeletons((v) => !v)} style={{ padding: '4px 10px', fontSize: 11 }}>Skeleton</button>
        <button type="button" className={'pill' + (showBoxes ? ' active' : '')} onClick={() => setShowBoxes((v) => !v)} style={{ padding: '4px 10px', fontSize: 11 }}>Box</button>
      </div>

      <div style={{ position: 'relative', width: '100%', maxWidth: 720, margin: '0 auto', borderRadius: 12, overflow: 'hidden', border: '1px solid rgba(255,255,255,0.07)', background: '#000' }}>
        <video
          ref={videoRef}
          src={`/fights/${fight.id}/video`}
          muted
          playsInline
          style={{ width: '100%', display: 'block' }}
          onPlay={() => setIsPlaying(true)}
          onPause={() => setIsPlaying(false)}
        />
        <FighterOverlay
          ref={overlayRef}
          frameMap={frameMap}
          fightWidth={fight.width}
          fightHeight={fight.height}
          showBoxes={showBoxes}
          showSkeletons={showSkeletons}
          highlightCorner={corner as 0 | 1 | null}
          cornerSwapSpans={cornerSwapSpans}
        />
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 11, flexWrap: 'wrap', marginTop: 11 }}>
        <button type="button" className="lab-ibtn" onClick={togglePlay} title="Play / pause — space" style={{ width: 32, height: 32, borderRadius: 8, display: 'grid', placeItems: 'center', background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border-glass)', color: 'var(--text-secondary)', cursor: 'pointer', flexShrink: 0 }}>
          <span className="material-symbols-outlined" style={{ fontSize: 16 }}>{isPlaying ? 'pause' : 'play_arrow'}</span>
        </button>
        <input
          type="range"
          min={windowStart}
          max={windowEnd}
          step={1 / fps}
          value={currentTime}
          onChange={(e) => handleScrub(Number(e.target.value))}
          style={{ flex: 1, minWidth: 140, accentColor: 'var(--cyan-400)', height: 4 }}
          aria-label="Frame"
        />
        <span style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 11, fontWeight: 700, color: 'var(--text-muted)' }}>
          {String(Math.min(clipFrame, clipFrames)).padStart(2, '0')} / {clipFrames}
        </span>
        <div style={{ display: 'flex', gap: 4, padding: 3, borderRadius: 9, background: 'rgba(0,0,0,0.28)', border: '1px solid var(--border-subtle)' }}>
          {[0.25, 0.5, 1].map((s) => (
            <button key={s} type="button" className={'pill' + (speed === s ? ' active' : '')} onClick={() => setSpeed(s)} style={{ padding: '4px 9px', fontSize: 11 }}>{s}×</button>
          ))}
        </div>
      </div>
      <div style={{ marginTop: 9, fontSize: 10.5, fontWeight: 600, color: 'var(--text-disabled)' }}>
        {fight.video_path.split('/').pop()} · {fps} fps
      </div>
    </div>
  );
}

import { useEffect, useCallback } from 'react';
import type { QAEvent } from '../../hooks/useTrainingDataEvents';
import type { TrainingClass } from '../../utils/trainingDataTaxonomy';
import type { ClassStats } from './ClassGrid';
import { formatFrameClock } from '../annotate/taxonomy';
import { fightLabel } from '../../utils/fightLabel';
import ClipPlayer from './ClipPlayer';
import VerdictBadge from './VerdictBadge';

const CORNER_C: Record<number, string> = { 0: 'var(--f-red)', 1: 'var(--f-blue)' };

function Meta({ k, v, mono, tone }: { k: string; v: React.ReactNode; mono?: boolean; tone?: string }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', gap: 14, padding: '7px 0', borderBottom: '1px solid rgba(255,255,255,0.045)' }}>
      <span style={{ fontSize: 10.5, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.08em', color: 'rgba(255,255,255,0.28)' }}>{k}</span>
      <span style={{ fontSize: 11.5, fontWeight: 700, color: tone ?? 'var(--text-secondary)', textAlign: 'right', fontFamily: mono ? 'ui-monospace,Menlo,monospace' : 'inherit', fontVariantNumeric: 'tabular-nums' }}>{v}</span>
    </div>
  );
}

interface EventReviewProps {
  event: QAEvent;
  cls: TrainingClass;
  onVerdict: (isVerified: boolean | null) => void;
  onBack: () => void;
  onJumpRelative: (delta: 1 | -1) => void;
  onJumpTo: (id: number) => void;
  queue: QAEvent[];
  pos: ClassStats;
}

export default function EventReview({ event, cls, onVerdict, onBack, onJumpRelative, onJumpTo, queue, pos }: EventReviewProps) {
  const v = event.is_verified;

  const act = useCallback((target: boolean) => {
    onVerdict(v === target ? null : target);
  }, [v, onVerdict]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === 'INPUT') return;
      if (e.key === 'c' || e.key === 'C') act(true);
      else if (e.key === 'x' || e.key === 'X') act(false);
      else if (e.key === 'ArrowRight') onJumpRelative(1);
      else if (e.key === 'ArrowLeft') onJumpRelative(-1);
      else if (e.key === 'Escape') onBack();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [act, onJumpRelative, onBack]);

  return (
    <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0,1fr) 330px', gap: 16, alignItems: 'start' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 }}>
        <div className="glass" style={{ padding: '14px 14px 12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 9, marginBottom: 11 }}>
            <span style={{ width: 10, height: 10, borderRadius: 3, flexShrink: 0, background: event.corner != null ? CORNER_C[event.corner] : 'var(--text-disabled)' }} />
            <div style={{ minWidth: 0 }}>
              <div className="font-display" style={{ fontSize: 22, lineHeight: 1, color: 'var(--text-primary)' }}>
                {cls.name}{event.target && <span> · {event.target}</span>}
              </div>
              <div style={{ marginTop: 3, fontSize: 11, fontWeight: 600, color: 'var(--text-muted)', fontVariantNumeric: 'tabular-nums' }}>
                {fightLabel(event.fight)} · {formatFrameClock(event.frame, event.fight.fps)} · f{event.frame}
              </div>
            </div>
          </div>
          <ClipPlayer fight={event.fight} frame={event.frame} corner={event.corner} />
        </div>

