import { useState, useMemo, useCallback, useEffect } from 'react';
import { useTrainingDataEvents } from '../hooks/useTrainingDataEvents';
import type { QAEvent } from '../hooks/useTrainingDataEvents';
import { TRAINING_CLASSES, CLASS_BY_ACTION } from '../utils/trainingDataTaxonomy';
import { useWindowWidth } from '../hooks/useWindowWidth';
import ClassGrid, { classStats } from '../components/trainingData/ClassGrid';
import EventTable from '../components/trainingData/EventTable';
import EventReview from '../components/trainingData/EventReview';

type View =
  | { v: 'classes' }
  | { v: 'events'; action: string }
  | { v: 'detail'; action: string; id: number }
  | { v: 'done'; action: string };

const sortEvents = (evs: QAEvent[]) =>
  [...evs].sort((a, b) => (a.fight.id === b.fight.id ? a.frame - b.frame : a.fight.id - b.fight.id));

export default function TrainingDataQA() {
  const width = useWindowWidth();
  const isMobile = width < 640;
  const narrow = width < 1080;

  const { events, fights, loading, error, setVerdict } = useTrainingDataEvents();
  const [view, setView] = useState<View>({ v: 'classes' });

  const eventsByAction = useMemo(() => {
    const m = new Map<string, QAEvent[]>();
    events.forEach((e) => {
      const key = e.action ?? '';
      const bucket = m.get(key);
      if (bucket) bucket.push(e); else m.set(key, [e]);
    });
    return m;
  }, [events]);

  const totals = classStats(events);

  const cls = view.v !== 'classes' ? CLASS_BY_ACTION[view.action] : null;
  const evs = useMemo(() => (cls ? sortEvents(eventsByAction.get(cls.action) ?? []) : []), [cls, eventsByAction]);
  const ev = view.v === 'detail' ? evs.find((e) => e.id === view.id) ?? null : null;

  useEffect(() => { window.scrollTo({ top: 0 }); }, [view.v, view.v === 'events' || view.v === 'detail' ? view.action : null]);

  const nextPending = useCallback((fromId: number): number | null => {
    const idx = evs.findIndex((e) => e.id === fromId);
    if (idx === -1) return null;
    for (let k = 1; k <= evs.length; k++) {
      const c = evs[(idx + k) % evs.length];
      if (c.is_verified == null) return c.id;
    }
    return null;
  }, [evs]);

  const onVerdict = useCallback((isVerified: boolean | null) => {
    if (view.v !== 'detail') return;
    const { action, id } = view;
    const fightId = ev?.fight.id;
    if (fightId == null) return;
    setVerdict(id, fightId, isVerified);
    if (isVerified == null) return; // clearing a verdict never auto-advances
    const nx = nextPending(id);
    if (nx != null) setTimeout(() => setView({ v: 'detail', action, id: nx }), 170);
    else setTimeout(() => setView({ v: 'done', action }), 240);
  }, [view, ev, setVerdict, nextPending]);

  const onJumpRelative = useCallback((delta: 1 | -1) => {
    if (view.v !== 'detail' || evs.length === 0) return;
    const idx = evs.findIndex((e) => e.id === view.id);
    const n = evs[(idx + delta + evs.length) % evs.length];
    setView({ v: 'detail', action: view.action, id: n.id });
  }, [view, evs]);

  const onJumpTo = useCallback((id: number) => {
    if (view.v !== 'detail') return;
    setView({ v: 'detail', action: view.action, id });
  }, [view]);

  let body: React.ReactNode;

  if (loading) {
    body = <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Loading…</div>;
  } else if (error) {
    body = <div style={{ fontSize: 13, color: 'var(--red-500)' }}>{error}</div>;
  } else if (fights.length === 0) {
    body = (
      <div className="glass" style={{ padding: '20px 22px', fontSize: 13, color: 'var(--text-muted)' }}>
        No labelled fights yet. Upload a fight as "Self-annotate" and start labelling it in Annotate to build training data.
      </div>
    );
  } else if (view.v === 'classes') {
    body = (
      <>
        <div style={{ display: 'flex', alignItems: 'flex-end', gap: 24, flexWrap: 'wrap', marginBottom: 14 }}>
          <div style={{ minWidth: 0 }}>
            <h1 className="font-display" style={{ fontSize: isMobile ? 30 : 40, lineHeight: 0.94, margin: 0, color: 'var(--text-primary)' }}>
              TRAINING DATA
            </h1>
            <p style={{ margin: '6px 0 0', fontSize: 12.5, fontWeight: 600, color: 'var(--text-muted)' }}>
              Every hand-labelled event as the trainer sees it — replay the clip, keep it or drop it
            </p>
          </div>
          <div style={{ display: 'flex', gap: 26, flexWrap: 'wrap', marginLeft: 'auto' }}>
            <Stat label="events" value={totals.total} />
            <Stat label="confirmed" value={totals.confirmed} color="#0ca30c" />
            <Stat label="declined" value={totals.declined} color="#ef4444" />
          </div>
        </div>
        {totals.total > 0 && (
          <div style={{ display: 'flex', gap: 2, height: 6, borderRadius: 3, background: 'rgba(255,255,255,0.05)', overflow: 'hidden', marginBottom: 7 }}>
            <div style={{ width: `${(totals.confirmed / totals.total) * 100}%`, background: '#0ca30c' }} />
            <div style={{ width: `${(totals.declined / totals.total) * 100}%`, background: '#ef4444' }} />
          </div>
        )}
        <div style={{ margin: '0 0 22px', fontSize: 11, fontWeight: 600, color: 'var(--text-muted)' }}>
          {totals.reviewed} of {totals.total} reviewed · {totals.pending} pending · across {fights.length} labelled fight{fights.length === 1 ? '' : 's'}
        </div>
        <ClassGrid eventsByAction={eventsByAction} onOpen={(action) => setView({ v: 'events', action })} />
      </>
    );
  } else if (view.v === 'events' && cls) {
    body = <EventTable cls={cls} events={evs} onBack={() => setView({ v: 'classes' })} onOpen={(id) => setView({ v: 'detail', action: cls.action, id })} />;
  } else if (view.v === 'done' && cls) {
    body = (
      <div className="glass" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 11, padding: '46px 30px', textAlign: 'center' }}>
        <span className="material-symbols-outlined" style={{ fontSize: 40, color: '#0ca30c' }}>task_alt</span>
        <div className="font-display" style={{ fontSize: 28, lineHeight: 1, color: 'var(--text-primary)' }}>{cls.name} reviewed</div>
        <p style={{ margin: 0, maxWidth: '46ch', fontSize: 12.5, fontWeight: 500, lineHeight: 1.6, color: 'var(--text-muted)' }}>
          Every {cls.name.toLowerCase()} event has a verdict. Pick another class or re-open the list.
        </p>
        <div style={{ display: 'flex', gap: 9, flexWrap: 'wrap', justifyContent: 'center' }}>
          <button type="button" className="btn-glass" onClick={() => setView({ v: 'events', action: cls.action })} style={{ padding: '9px 16px', fontSize: 12.5, fontWeight: 600, borderRadius: 8 }}>
            Back to events
          </button>
          <button
            type="button"
            onClick={() => setView({ v: 'classes' })}
            style={{
              background: 'linear-gradient(135deg, #00daf3 0%, #0099b0 100%)', color: '#001f24', fontWeight: 700, fontSize: 13,
              border: 'none', borderRadius: 10, padding: '9px 16px', cursor: 'pointer',
            }}
          >
            All classes
          </button>
        </div>
      </div>
    );
  } else if (view.v === 'detail' && cls && ev) {
    body = (
      <>
        <div style={{ display: 'flex', alignItems: 'center', gap: 9, marginBottom: 14, flexWrap: 'wrap' }}>
          <button type="button" className="btn-glass" onClick={() => setView({ v: 'classes' })} style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '5px 10px', fontSize: 11.5, fontWeight: 700, borderRadius: 8 }}>
            <span className="material-symbols-outlined" style={{ fontSize: 15 }}>arrow_back</span>All classes
          </button>
          <span style={{ color: 'var(--text-disabled)', fontSize: 12 }}>/</span>
          <button type="button" className="btn-glass" onClick={() => setView({ v: 'events', action: cls.action })} style={{ padding: '5px 10px', fontSize: 11.5, fontWeight: 700, borderRadius: 8, background: 'none', border: '1px solid transparent' }}>
            {cls.name}
          </button>
          <span style={{ color: 'var(--text-disabled)', fontSize: 12 }}>/</span>
          <span style={{ fontSize: 11.5, fontWeight: 700, color: 'var(--text-secondary)' }}>{`f${ev.frame}`}</span>
        </div>
        <EventReview
          event={ev}
          cls={cls}
          onVerdict={onVerdict}
          onBack={() => setView({ v: 'events', action: cls.action })}
          onJumpRelative={onJumpRelative}
          onJumpTo={onJumpTo}
          queue={evs.filter((e) => e.is_verified == null && e.id !== ev.id)}
          pos={classStats(evs)}
          narrow={narrow}
        />
      </>
    );
  } else {
    // Stale view (e.g. the event was filtered out from under it) — fall back.
    body = <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Nothing here — go back to classes.</div>;
  }

  return (
    <div style={{ position: 'relative', zIndex: 1, maxWidth: 1320, margin: '0 auto', padding: isMobile ? '18px 16px 70px' : '22px 30px 90px' }}>
      {body}
    </div>
  );
}

function Stat({ label, value, color }: { label: string; value: number; color?: string }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
      <span className="font-display" style={{ fontSize: 30, lineHeight: 1, color: color ?? 'var(--text-primary)' }}>{value}</span>
      <span className="label">{label}</span>
    </div>
  );
}

